{
  "items": [
    {
      "name": "MvPolynomial.coeffs",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "definition",
      "type": "{R : Type u} → {σ : Type u_1} → [inst : CommSemiring R] → MvPolynomial σ R → Finset R"
    },
    {
      "name": "MvPowerSeries.coeff_prod",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Basic",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_3} [inst : CommSemiring R] {ι : Type u_4} [inst_1 : DecidableEq ι] [inst_2 : DecidableEq σ]\n  (f : ι → MvPowerSeries σ R) (d : σ →₀ ℕ) (s : Finset ι),\n  (MvPowerSeries.coeff d) (∏ j ∈ s, f j) = ∑ l ∈ s.finsuppAntidiag d, ∏ i ∈ s, (MvPowerSeries.coeff (l i)) (f i)"
    },
    {
      "name": "MvPolynomial.coeff",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "definition",
      "type": "{R : Type u} → {σ : Type u_1} → [inst : CommSemiring R] → (σ →₀ ℕ) → MvPolynomial σ R → R"
    },
    {
      "name": "MvPolynomial.coeff_mul",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] [inst_1 : DecidableEq σ] (p q : MvPolynomial σ R) (n : σ →₀ ℕ),\n  MvPolynomial.coeff n (p * q) = ∑ x ∈ Finset.antidiagonal n, MvPolynomial.coeff x.1 p * MvPolynomial.coeff x.2 q"
    },
    {
      "name": "MvPowerSeries.coeff_mul",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Basic",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] (n : σ →₀ ℕ) (φ ψ : MvPowerSeries σ R) [inst_1 : DecidableEq σ],\n  (MvPowerSeries.coeff n) (φ * ψ) =\n    ∑ p ∈ Finset.antidiagonal n, (MvPowerSeries.coeff p.1) φ * (MvPowerSeries.coeff p.2) ψ"
    },
    {
      "name": "MonomialOrder.coeff_prod_sum_degree",
      "module_name": "Mathlib.RingTheory.MvPolynomial.MonomialOrder",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {m : MonomialOrder σ} {R : Type u_2} [inst : CommSemiring R] {ι : Type u_3} (P : ι → MvPolynomial σ R)\n  (s : Finset ι), MvPolynomial.coeff (∑ i ∈ s, m.degree (P i)) (∏ i ∈ s, P i) = ∏ i ∈ s, m.leadingCoeff (P i)"
    },
    {
      "name": "Polynomial.leadingCoeff_prod",
      "module_name": "Mathlib.Algebra.Polynomial.BigOperators",
      "kind": "theorem",
      "type": "∀ {R : Type u} {ι : Type w} (s : Finset ι) [inst : CommSemiring R] [NoZeroDivisors R] (f : ι → Polynomial R),\n  (∏ i ∈ s, f i).leadingCoeff = ∏ i ∈ s, (f i).leadingCoeff"
    },
    {
      "name": "MonomialOrder.leadingCoeff_prod_of_mem_nonZeroDivisors",
      "module_name": "Mathlib.RingTheory.MvPolynomial.MonomialOrder",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {m : MonomialOrder σ} {R : Type u_2} [inst : CommSemiring R] {ι : Type u_3} {P : ι → MvPolynomial σ R}\n  {s : Finset ι},\n  (∀ i ∈ s, m.leadingCoeff (P i) ∈ nonZeroDivisors R) → m.leadingCoeff (∏ i ∈ s, P i) = ∏ i ∈ s, m.leadingCoeff (P i)"
    }
  ]
}

